ALTER TABLE FengTu_PL_Email_Archive RENAME TO FengTu_PL_Email_Archive_Legacy;
CREATE TABLE FengTu_PL_Email_Archive (id INTEGER PRIMARY KEY AUTOINCREMENT, account_id BIGINT NOT NULL, account_email VARCHAR(320) NOT NULL, folder VARCHAR(500) NOT NULL, message_uid VARCHAR(255) NOT NULL, subject VARCHAR(998), from_address VARCHAR(1000), recipients_json TEXT, sent_at INTEGER, received_at INTEGER, has_attachment INTEGER NOT NULL DEFAULT 0, body_preview VARCHAR(500), eml_path VARCHAR(2000) NOT NULL, archived_at INTEGER NOT NULL DEFAULT (unixepoch('subsec') * 1000), UNIQUE(account_id, folder, message_uid));
INSERT INTO FengTu_PL_Email_Archive(id, account_id, account_email, folder, message_uid, subject, from_address, recipients_json, sent_at, received_at, has_attachment, body_preview, eml_path, archived_at) SELECT id, account_id, account_email, folder, message_uid, subject, from_address, recipients_json, CASE WHEN sent_at IS NULL THEN NULL WHEN TRIM(CAST(sent_at AS TEXT)) NOT GLOB '*[^0-9]*' THEN CAST(sent_at AS INTEGER) ELSE CAST((julianday(sent_at) - 2440587.5) * 86400000 AS INTEGER) END, CASE WHEN received_at IS NULL THEN NULL WHEN TRIM(CAST(received_at AS TEXT)) NOT GLOB '*[^0-9]*' THEN CAST(received_at AS INTEGER) ELSE CAST((julianday(received_at) - 2440587.5) * 86400000 AS INTEGER) END, has_attachment, body_preview, eml_path, COALESCE(CASE WHEN TRIM(CAST(archived_at AS TEXT)) NOT GLOB '*[^0-9]*' THEN CAST(archived_at AS INTEGER) ELSE CAST((julianday(archived_at) - 2440587.5) * 86400000 AS INTEGER) END, unixepoch('subsec') * 1000) FROM FengTu_PL_Email_Archive_Legacy;
DROP TABLE FengTu_PL_Email_Archive_Legacy;
CREATE INDEX FengTu_PL_Email_Archive_Query_Idx ON FengTu_PL_Email_Archive(account_id, sent_at, subject);
INSERT INTO FengTu_PL_Email_Schema_History(version) VALUES (2);
